using Microsoft.ML.Data;

namespace TicketClassifier.Models;

/// <summary>
/// Input schema that maps to the training CSV columns.
/// </summary>
public class TicketData
{
    [LoadColumn(0)]
    public string Subject { get; set; } = string.Empty;

    [LoadColumn(1)]
    public string Description { get; set; } = string.Empty;

    [LoadColumn(2)]
    public float Priority { get; set; }

    [LoadColumn(3)]
    public string Category { get; set; } = string.Empty;
}

/// <summary>
/// ML.NET prediction output.
/// </summary>
public class TicketPrediction
{
    [ColumnName("PredictedLabel")]
    public string PredictedCategory { get; set; } = string.Empty;

    public float[] Score { get; set; } = [];
}

namespace TicketClassifier.Models;

/// <summary>
/// API request body for ticket classification.
/// </summary>
public class TicketRequest
{
    public required string Subject { get; set; }
    public required string Description { get; set; }
    public int Priority { get; set; }
}

/// <summary>
/// API response with predicted category and per-class confidence scores.
/// </summary>
public class TicketResponse
{
    public required string PredictedCategory { get; set; }
    public required Dictionary<string, float> Confidence { get; set; }
}

/// <summary>
/// Model evaluation metrics returned from the training endpoint.
/// </summary>
public class TrainingMetrics
{
    public float MicroAccuracy { get; set; }
    public float MacroAccuracy { get; set; }
    public float LogLoss { get; set; }
    public float LogLossReduction { get; set; }
}

using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

/// <summary>
/// Trains and evaluates the multiclass classification model at startup.
/// </summary>
public class ModelTrainerService
{
    private readonly string _dataPath;
    private readonly string _modelPath;
    private readonly ILogger<ModelTrainerService> _logger;
    private TrainingMetrics? _metrics;

    public TrainingMetrics? Metrics => _metrics;

    public ModelTrainerService(IWebHostEnvironment env, ILogger<ModelTrainerService> logger)
    {
        _dataPath = Path.Combine(env.ContentRootPath, "Data", "tickets.csv");
        _modelPath = Path.Combine(env.ContentRootPath, "Data", "model.zip");
        _logger = logger;
    }

    public string ModelPath => _modelPath;

    public void TrainAndEvaluate()
    {
        var mlContext = new MLContext(seed: 42);

        IDataView data = mlContext.Data.LoadFromTextFile<TicketData>(
            _dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        // Combine text features and the numeric priority into a single feature vector.
        var pipeline = mlContext.Transforms.Conversion.MapValueToKey("Label", nameof(TicketData.Category))
            .Append(mlContext.Transforms.Text.FeaturizeText("SubjectFeaturized", nameof(TicketData.Subject)))
            .Append(mlContext.Transforms.Text.FeaturizeText("DescriptionFeaturized", nameof(TicketData.Description)))
            .Append(mlContext.Transforms.Concatenate("Features",
                "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketData.Priority)))
            .Append(mlContext.Transforms.NormalizeMinMax("Features"))
            .Append(mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy(
                labelColumnName: "Label", featureColumnName: "Features"))
            .Append(mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        // With only 6 rows, cross-validation gives a better signal than a single split.
        var cvResults = mlContext.MulticlassClassification.CrossValidate(data, pipeline, numberOfFolds: 3);

        _metrics = new TrainingMetrics
        {
            MicroAccuracy = (float)cvResults.Average(r => r.Metrics.MicroAccuracy),
            MacroAccuracy = (float)cvResults.Average(r => r.Metrics.MacroAccuracy),
            LogLoss = (float)cvResults.Average(r => r.Metrics.LogLoss),
            LogLossReduction = (float)cvResults.Average(r => r.Metrics.LogLossReduction),
        };

        _logger.LogInformation(
            "Model trained — MicroAccuracy: {Micro:F4}, MacroAccuracy: {Macro:F4}, LogLoss: {LogLoss:F4}",
            _metrics.MicroAccuracy, _metrics.MacroAccuracy, _metrics.LogLoss);

        // Train final model on full dataset and save.
        var model = pipeline.Fit(data);
        mlContext.Model.Save(model, data.Schema, _modelPath);
        _logger.LogInformation("Model saved to {Path}", _modelPath);
    }
}

using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

namespace TicketClassifier.Controllers;

[ApiController]
[Route("api/[controller]")]
public class TicketController : ControllerBase
{
    private readonly PredictionEnginePool<TicketData, TicketPrediction> _pool;
    private readonly ModelTrainerService _trainer;

    private static readonly string[] CategoryLabels = ["Billing", "General", "Technical"];

    public TicketController(
        PredictionEnginePool<TicketData, TicketPrediction> pool,
        ModelTrainerService trainer)
    {
        _pool = pool;
        _trainer = trainer;
    }

    /// <summary>
    /// Classify a support ticket.
    /// </summary>
    [HttpPost("classify")]
    public ActionResult<TicketResponse> Classify([FromBody] TicketRequest request)
    {
        var input = new TicketData
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority,
        };

        var prediction = _pool.Predict(input);

        var confidence = new Dictionary<string, float>();
        for (int i = 0; i < CategoryLabels.Length && i < prediction.Score.Length; i++)
        {
            confidence[CategoryLabels[i]] = prediction.Score[i];
        }

        return Ok(new TicketResponse
        {
            PredictedCategory = prediction.PredictedCategory,
            Confidence = confidence,
        });
    }

    /// <summary>
    /// Return evaluation metrics from the last training run.
    /// </summary>
    [HttpGet("metrics")]
    public ActionResult<TrainingMetrics> GetMetrics()
    {
        if (_trainer.Metrics is null)
            return NotFound("Model has not been trained yet.");

        return Ok(_trainer.Metrics);
    }
}

