using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();

// Register the trainer as a singleton so metrics survive across requests.
builder.Services.AddSingleton<ModelTrainerService>();

// PredictionEnginePool: thread-safe prediction for ASP.NET Core.
// The model file path is resolved after training runs at startup.
builder.Services.AddPredictionEnginePool<TicketData, TicketPrediction>();

var app = builder.Build();

// Train the model at startup and configure the pool to load the saved model.
var trainer = app.Services.GetRequiredService<ModelTrainerService>();
trainer.TrainAndEvaluate();

var poolOptions = app.Services
    .GetRequiredService<Microsoft.Extensions.Options.IOptions<
        Microsoft.Extensions.ML.PredictionEnginePoolOptions<TicketData, TicketPrediction>>>()
    .Value;
poolOptions.ModelLoader = new Microsoft.ML.ModelLoader(trainer.ModelPath);

app.MapControllers();
app.Run();

